"""
Primitivity explorer for Fibonacci Pythagorean triples.

For each n, the triple (a, b, c) with a = F_n F_{n+3}, b = 2 F_{n+1} F_{n+2},
c = F_{n+1}^2 + F_{n+2}^2 is generated, and gcd(a, b, c) is computed.  The
conjecture states that the triple is primitive (gcd = 1) exactly when
n not congruent to 1 (mod 3), and gcd = 2 when n congruent to 1 (mod 3).
"""

from __future__ import annotations

from math import gcd
from typing import Tuple


def fib(n: int) -> int:
    a, b = 0, 1
    for _ in range(n):
        a, b = b, a + b
    return a


def triple(n: int) -> Tuple[int, int, int]:
    fn, fn1, fn2, fn3 = fib(n), fib(n + 1), fib(n + 2), fib(n + 3)
    return (fn * fn3, 2 * fn1 * fn2, fn1 * fn1 + fn2 * fn2)


def triple_gcd(n: int) -> int:
    a, b, c = triple(n)
    return gcd(gcd(a, b), c)


def main() -> None:
    print(f"{'n':>3} {'a':>7} {'b':>8} {'c':>8} {'gcd':>4} {'n mod 3':>8} {'primitive':>10}")
    for n in range(1, 19):
        a, b, c = triple(n)
        g = gcd(gcd(a, b), c)
        print(f"{n:>3} {a:>7} {b:>8} {c:>8} {g:>4} {n % 3:>8} {str(g == 1):>10}")
    ok = all((triple_gcd(n) == (2 if n % 3 == 1 else 1)) for n in range(1, 200))
    print("Conjecture (gcd = 2 iff n = 1 mod 3, else 1) holds for n=1..199:", ok)


if __name__ == "__main__":
    main()

