function TRIPLE(n):
    (F_n, F_{n+1}) <- FIB_PAIR(n)          # fast doubling, O(log n)
    F_{n+2} <- F_n + F_{n+1}
    F_{n+3} <- F_{n+1} + F_{n+2}
    a <- F_n * F_{n+3}                     # p^2 - q^2
    b <- 2 * F_{n+1} * F_{n+2}             # 2 p q
    c <- F_{n+1}^2 + F_{n+2}^2             # p^2 + q^2 = F_{2n+3}
    return (a, b, c)

function FIB_PAIR(n):                      # returns (F_n, F_{n+1})
    if n = 0: return (0, 1)
    (a, b) <- FIB_PAIR(floor(n/2))
    c <- a * (2b - a);  d <- a^2 + b^2
    if n odd: return (d, c + d) else return (c, d)

