from typing import Tuple


def fib_pair(n: int) -> Tuple[int, int]:
    """Return (F_n, F_{n+1}) via fast doubling in O(log n) big-int operations."""
    if n == 0:
        return (0, 1)
    a, b = fib_pair(n >> 1)
    c = a * (2 * b - a)      # F_{2m}
    d = a * a + b * b        # F_{2m+1}
    return (d, c + d) if (n & 1) else (c, d)


def fibonacci_pythagorean_triple(n: int) -> Tuple[int, int, int]:
    """Return the n-th Fibonacci Pythagorean triple (a, b, c)."""
    fn, fn1 = fib_pair(n)
    fn2 = fn + fn1
    fn3 = fn1 + fn2
    a = fn * fn3               # p^2 - q^2  with p = F_{n+2}, q = F_{n+1}
    b = 2 * fn1 * fn2          # 2 p q
    c = fn1 * fn1 + fn2 * fn2  # p^2 + q^2  = F_{2n+3}
    return (a, b, c)

