from typing import Dict


def fib(n: int) -> int:
    a, b = 0, 1
    for _ in range(n):
        a, b = b, a + b
    return a


def verify_all_identities(n: int) -> Dict[str, bool]:
    """Exactly verify every closed-form identity for the n-th triple."""
    fn, fn1, fn2, fn3 = fib(n), fib(n + 1), fib(n + 2), fib(n + 3)
    a = fn * fn3
    b = 2 * fn1 * fn2
    c = fn1 * fn1 + fn2 * fn2
    return {
        "pythagorean":        a * a + b * b == c * c,
        "hypotenuse_is_fib":  c == fib(2 * n + 3),
        "area_is_product":    a * b == 2 * fn * fn1 * fn2 * fn3,
        "perimeter":          a + b + c == 2 * fn2 * fn3,
        "inradius":           a + b - c == 2 * fn * fn1,
    }

